UPDATE public.lessons SET content = '<section class="lesson-section"><h3>Learning Objective</h3><p>Design a healthcare analysis around a clinical workflow, missingness, privacy, and the consequences of errors.</p></section>
<section class="lesson-section"><h3>Story</h3><p>A hospital studies whether staffing levels relate to emergency department waiting time.</p></section>
<section class="lesson-section"><h3>Discovery</h3><p>Do staffing records and wait-time measures cover the same shifts and patient groups?</p></section>
